INIT_COUNT = 0
def init():
    global INIT_COUNT
    INIT_COUNT += 1
    return {"client": "s3"}
CLIENT = init()          # module level: runs once per container (cold start)
calls = []
def handler(event, context=None):
    calls.append(event["id"])
    return {"init": INIT_COUNT, "seen": len(calls)}
for i in range(3):
    r = handler({"id": i})
print(r)
